const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;
const signature = String(headers['x-hub-signature-256'] || '').replace(/^sha256=/, '');
const raw = input.rawBody || JSON.stringify(body);
const expected = crypto.createHmac('sha256', $env.GITHUB_WEBHOOK_SECRET).update(raw).digest('hex');
if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new Error('invalid GitHub signature');
const delivery = String(headers['x-github-delivery'] || '');
if (!delivery) throw new Error('missing GitHub delivery ID');
const sha = String(body.after || '');
if (!/^[0-9a-f]{40}$/.test(sha) || /^0+$/.test(sha)) throw new Error('push does not identify a full head SHA');
const head = (body.commits || []).find(c => c.id === sha) || body.head_commit;
if (!head || head.id !== sha) throw new Error('head commit is absent from payload');
const lines = String(head.message || '').trimEnd().split(/\r?\n/);
let i = lines.length - 1; const trailers = {};
while (i >= 0 && /^([A-Za-z0-9-]+):\s*(.+)$/.test(lines[i])) { const m = lines[i].match(/^([A-Za-z0-9-]+):\s*(.+)$/); if (trailers[m[1]]) throw new Error('duplicate commit trailer'); trailers[m[1]] = m[2].trim(); i--; }
if (!/^atj_[a-f0-9]{32}$/.test(trailers['AI-Test-Job'] || '') || trailers['AI-Test-Phase'] !== 'verify') throw new Error('missing or invalid AI test trailers');
const repository = String(body.repository?.full_name || '').toLowerCase();
const branch = String(body.ref || '').replace(/^refs\/heads\//, '');
const allowed = String($env.AI_TEST_ALLOWED_REPOSITORIES || '').split(',').map(v => v.trim().toLowerCase()).filter(Boolean);
if (!allowed.includes(repository)) throw new Error('repository is not allowlisted');
return [{ json: { jobId: trailers['AI-Test-Job'], request: { repository: 'github.com/' + repository, branch, code_sha: sha, push_event_id: delivery } } }];
